diff --git a/src/domain/batches.js b/src/domain/batches.js
index ee14fde..3c16e92 100644
--- a/src/domain/batches.js
+++ b/src/domain/batches.js
@@ -18,9 +18,20 @@ export function getBatch(store, id) {
   return batch;
 }

-// The order in which an item's batches are used up.
+// The order in which an item's batches are used up (FEFO, see docs/DATA.md).
 function consumptionOrder(batches) {
-  return [...batches].sort((a, b) => b.receivedOn.localeCompare(a.receivedOn));
+  return [...batches].sort((a, b) => {
+    const aExp = a.expires || null;
+    const bExp = b.expires || null;
+    if (aExp !== bExp) {
+      if (!aExp) return 1;
+      if (!bExp) return -1;
+      return aExp.localeCompare(bExp);
+    }
+    const rec = a.receivedOn.localeCompare(b.receivedOn);
+    if (rec !== 0) return rec;
+    return a.id - b.id;
+  });
 }

